_CORE_SRC = '# Diagnosis:\n# The remaining loss to best-response is consistent with planning/forecast error,\n# not legality. The champion restarts all reservations as stationary every turn:\n# coordinated routes found last turn are discarded, and early truck decisions\n# are made against scooters that unrealistically stay put. Its beam also fills\n# with nearly identical paths, often excluding a useful return-home route.\n#\n# Changes:\n# Preserve shifted, legal route reservations across turns, and compare every\n# replacement against the complete incumbent route (never replace it merely\n# because a narrow beam missed it). Use a longer horizon and position-diverse\n# beams. This particularly helps expensive trucks retire while scooters take\n# over regeneration, without paying repeated deployment costs.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nCAP = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\ndef margin(a, b, stock):\n    den = max(a + b, stock)\n    return (a - b) * stock / den if den > 0 else 0.0\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.key = None\n        self.dist = []\n        self.reach = {}\n        self.saved = {}\n        self.last_turn = None\n        self.previous = {}\n        self.mobility = 0.7\n        self.bad = 0\n\n    def build(self, n, edges):\n        adj = [[] for _ in range(n)]\n        for a, b in edges:\n            adj[a].append(b)\n            adj[b].append(a)\n        self.dist = []\n        for s in range(n):\n            d = [n + 1] * n\n            d[s] = 0\n            q = deque([s])\n            while q:\n                u = q.popleft()\n                for v in sorted(adj[u]):\n                    if d[v] > d[u] + 1:\n                        d[v] = d[u] + 1\n                        q.append(v)\n            self.dist.append(d)\n        self.reach = {\n            sp: [[v for v in range(n) if self.dist[u][v] <= sp]\n                 for u in range(n)] for sp in (1, 2)\n        }\n\n    def forecast(self, obs, horizon, deadline):\n        n = obs["n_nodes"]\n        units = obs["opponent_units"]\n        home = obs["opponent_base"]\n        positions = {u: d[1] for u, d in units.items()}\n        stationary = [0.0] * n\n        ours = [0.0] * n\n        for kind, node in units.values():\n            stationary[node] += CAP[kind]\n        for kind, node in obs["player_units"].values():\n            ours[node] += CAP[kind]\n        stock = list(obs["stock"])\n        blend = min(0.94, max(0.12, 0.35 + self.mobility))\n        if self.mobility < 0.06:\n            blend = 0.06\n        result = []\n        order = sorted(units, key=lambda u: (units[u][0] != "truck", u))\n        for t in range(horizon):\n            caps = [0.0] * n\n            for uid in order:\n                kind = units[uid][0]\n                cap, cost, speed = CAP[kind], COST[kind], SPEED[kind]\n                start = positions[uid]\n                best, bv = start, -1e30\n                for v in self.reach[speed][start]:\n                    other = ours[v] * (0.65 ** t)\n                    value = (margin(caps[v] + cap, other, stock[v])\n                             - margin(caps[v], other, stock[v]))\n                    if v != home:\n                        value -= cost\n                    if v == start:\n                        value += 0.025\n                    if value > bv:\n                        best, bv = v, value\n                positions[uid] = best\n                caps[best] += cap\n            pred = [blend * caps[v] + (1 - blend) * stationary[v]\n                    for v in range(n)]\n            result.append(pred)\n            stock = [\n                min(obs["stock_max"][v],\n                    max(0.0, stock[v] - pred[v] - ours[v] * (0.65 ** t))\n                    + obs["regen"][v])\n                for v in range(n)\n            ]\n            if time.perf_counter() >= deadline:\n                result.extend([pred[:] for _ in range(horizon - len(result))])\n                break\n        return result\n\n    def route(self, start, kind, allocation, opponent, obs, old, deadline):\n        n = obs["n_nodes"]\n        horizon = len(allocation)\n        cap, cost, speed = CAP[kind], COST[kind], SPEED[kind]\n        home = obs["player_base"]\n        maxima, regen = obs["stock_max"], obs["regen"]\n        stocks = list(obs["stock"])\n        baseline = []\n        for t in range(horizon):\n            a, b = allocation[t], opponent[t]\n            baseline.append(sum(margin(a[v], b[v], stocks[v])\n                                for v in range(n)))\n            stocks = [min(maxima[v], max(0.0, stocks[v] - a[v] - b[v])\n                          + regen[v]) for v in range(n)]\n\n        remaining = 60 - obs["turn"]\n\n        def liability(dest, t):\n            steps = (self.dist[dest][home] + speed - 1) // speed\n            return 0.35 * cost * min(steps, max(0, remaining - t - 1))\n\n        # Score the incumbent exactly using the same objective as the search.\n        stocks = list(obs["stock"])\n        incumbent = 0.0\n        pos = start\n        for t, dest in enumerate(old):\n            a, b = allocation[t], opponent[t]\n            total = 0.0\n            ns = []\n            for v in range(n):\n                own = a[v] + (cap if v == dest else 0)\n                total += margin(own, b[v], stocks[v])\n                ns.append(min(maxima[v],\n                              max(0.0, stocks[v] - own - b[v]) + regen[v]))\n            incumbent += total - baseline[t] - (cost if dest != home else 0)\n            incumbent += 0.001 if dest == pos else 0.0\n            pos = dest\n            stocks = ns\n        incumbent -= liability(old[-1], horizon - 1)\n\n        beam = [(0.0, start, list(obs["stock"]), ())]\n        width = 16\n        for t in range(horizon):\n            if time.perf_counter() >= deadline:\n                return old\n            a, b = allocation[t], opponent[t]\n            expanded = []\n            for value, pos, stocks, path in beam:\n                local = [margin(a[v], b[v], stocks[v]) for v in range(n)]\n                background = sum(local) - baseline[t]\n                next_stock = [\n                    min(maxima[v], max(0.0, stocks[v] - a[v] - b[v]) + regen[v])\n                    for v in range(n)\n                ]\n                for dest in self.reach[speed][pos]:\n                    raw = (value + background\n                           + margin(a[dest] + cap, b[dest], stocks[dest])\n                           - local[dest] - (cost if dest != home else 0))\n                    if dest == pos:\n                        raw += 0.001\n                    ns = next_stock[:]\n                    ns[dest] = min(\n                        maxima[dest],\n                        max(0.0, stocks[dest] - a[dest] - b[dest] - cap)\n                        + regen[dest])\n                    expanded.append((raw - liability(dest, t), raw, dest,\n                                     ns, path + (dest,)))\n            expanded.sort(key=lambda x: (-x[0], x[4]))\n            # Retain the best route ending at each position before using spare\n            # slots for alternative stock histories at the same position.\n            selected, extras = [], []\n            seen = set()\n            for item in expanded:\n                if item[2] not in seen:\n                    seen.add(item[2])\n                    selected.append(item)\n                else:\n                    extras.append(item)\n            selected = (selected + extras[:max(0, width - len(selected))])[:width]\n            beam = [(x[1], x[2], x[3], x[4]) for x in selected]\n\n        best = max(beam, key=lambda x: x[0] - liability(x[1], horizon - 1))\n        score = best[0] - liability(best[1], horizon - 1)\n        return best[3] if score > incumbent + 1e-8 else old\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0001, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        units = obs.get("player_units", {})\n        if n <= 0 or not units:\n            return {"moves": {}}\n        key = (n, tuple(tuple(e) for e in obs.get("edges", [])))\n        if key != self.key:\n            self.build(n, obs["edges"])\n            self.key = key\n            self.saved = {}\n        turn = int(obs.get("turn", 0))\n        consecutive = self.last_turn is not None and turn == self.last_turn + 1\n        enemies = obs.get("opponent_units", {})\n        if consecutive and self.previous:\n            fraction = sum(d[1] != self.previous.get(u, d[1])\n                           for u, d in enemies.items()) / max(1, len(enemies))\n            self.mobility = 0.65 * self.mobility + 0.35 * fraction\n        self.previous = {u: d[1] for u, d in enemies.items()}\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0)):\n            self.bad += 1\n        horizon = max(1, min(8, 60 - turn))\n        if self.bad >= 2:\n            horizon = min(horizon, 2)\n        opponent = self.forecast(obs, horizon, deadline)\n        routes = {}\n        allocated = [[0.0] * n for _ in range(horizon)]\n        for uid, (kind, start) in units.items():\n            path = []\n            if consecutive and uid in self.saved and self.bad < 2:\n                prior = self.saved[uid]\n                if prior and prior[0] == start:\n                    path = list(prior[1:horizon + 1])\n            pos = start\n            valid = []\n            for dest in path:\n                if not (0 <= dest < n and self.dist[pos][dest] <= SPEED[kind]):\n                    break\n                valid.append(dest)\n                pos = dest\n            valid.extend([pos] * (horizon - len(valid)))\n            routes[uid] = tuple(valid)\n            for t, dest in enumerate(valid):\n                allocated[t][dest] += CAP[kind]\n\n        order = sorted(units, key=lambda u: (units[u][0] != "truck", u))\n        # Alternating order lets cheap couriers displace trucks on later sweeps.\n        for sweep in range(4):\n            sequence = order if sweep % 2 == 0 else list(reversed(order))\n            for uid in sequence:\n                if time.perf_counter() >= deadline:\n                    break\n                kind, start = units[uid]\n                old = routes[uid]\n                cap = CAP[kind]\n                for t, dest in enumerate(old):\n                    allocated[t][dest] -= cap\n                new = self.route(start, kind, allocated, opponent,\n                                 obs, old, deadline)\n                routes[uid] = new\n                for t, dest in enumerate(new):\n                    allocated[t][dest] += cap\n            if time.perf_counter() >= deadline:\n                break\n        self.saved = routes\n        self.last_turn = turn\n        moves = {}\n        for uid in sorted(units):\n            kind, start = units[uid]\n            dest = int(routes[uid][0])\n            if (dest != start and 0 <= dest < n\n                    and self.dist[start][dest] <= SPEED[kind]):\n                moves[str(uid)] = int(dest)\n        return {"moves": moves}\n'
